# ============================================================
# AEGIS NIDS - STEP 12: Performance Benchmarking
# ============================================================
# Measures throughput (events/sec) and latency (ns/event) of the full
# Golden Path pipeline. Provides layer-by-layer breakdown to identify
# bottlenecks.
#
# Benchmarks:
#   1. Baseline (canonical.create only) — measures event creation overhead
#   2. Full pipeline throughput (RAG+flow+detection+correlation+policy+forensics)
#   3. Forensics ring buffer write throughput
#   4. Replay query throughput (scan 1000 records)
#   5. Layer-by-layer breakdown (RAG vs flow vs detection vs correlation
#      vs policy vs forensics) with percentage of total time
#
# Assertions (also serve as tests):
#   - Full pipeline throughput >= 1000 events/sec
#   - Pipeline overhead < 1000x baseline
#   - Layer breakdown percentages sum correctly
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 12 - Performance Benchmarking"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
        Write-Host "  [MKDIR] Created: $Dir"
    }
    $BackupPath = "$FullPath.step12_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/perf_benchmark.zig (perf_benchmark.zig, 535 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/perf_benchmark.zig" -ExpectedLines 535 -Base64Content $B64_1
Write-Host ""

# File 2: build.zig (build.zig, 86 lines)
$B64_2 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 86 -Base64Content $B64_2
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) {
    Write-Host "[BUILD] FAILED (exit $buildExit)"
    exit 1
}
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test (includes benchmarks as tests)..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED (including benchmarks)"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

Write-Host "============================================================"
Write-Host "STEP 12 COMPLETE: Performance Benchmarking"
Write-Host "============================================================"
Write-Host ""
Write-Host "Files deployed:"
Write-Host "  core/perf_benchmark.zig  (NEW, 525 lines)"
Write-Host "    - BenchmarkResult: name, iterations, total_ns, avg_ns_per_op,"
Write-Host "      ops_per_sec, min_ns, max_ns + print() method"
Write-Host "    - LayerBreakdown: per-layer ns + percentage of total + print()"
Write-Host "    - 5 benchmark functions:"
Write-Host "      1. benchmarkBaseline(): canonical.create only (control)"
Write-Host "      2. benchmarkFullPipeline(): full Golden Path per event"
Write-Host "      3. benchmarkForensicsWrite(): ring buffer write throughput"
Write-Host "      4. benchmarkReplayQuery(): scan 1000 records"
Write-Host "      5. benchmarkLayerBreakdown(): per-layer timing"
Write-Host "    - runAllBenchmarks(iterations): runs all + prints summary"
Write-Host "    - 9 tests: value types, completion, throughput threshold,"
Write-Host "      overhead bound, percentage sum"
Write-Host ""
Write-Host "  build.zig              (REPLACE, 86 lines)"
Write-Host "    - Added core/perf_benchmark.zig (30 entries)"
Write-Host ""
Write-Host "Benchmark output format (when runAllBenchmarks called):"
Write-Host "  [BENCH] Baseline: 1000 ops in 5ms | avg=5000ns/op | 200000 ops/sec"
Write-Host "  [BENCH] Full Pipeline: 500 ops in 250ms | avg=500000ns/op | 2000 ops/sec"
Write-Host "  [BENCH] Layer breakdown (avg ns/event):"
Write-Host "    RAG:         50000ns (10%)"
Write-Host "    Flow:        80000ns (16%)"
Write-Host "    Detection:   30000ns (6%)"
Write-Host "    Correlation: 120000ns (24%)"
Write-Host "    Policy:      70000ns (14%)"
Write-Host "    Forensics:   150000ns (30%)"
Write-Host "    TOTAL:       500000ns"
Write-Host "  [BENCH] Pipeline overhead: 100x baseline"
Write-Host "  [BENCH] Throughput: 2000 events/sec"
Write-Host ""
Write-Host "Throughput assertions:"
Write-Host "  - Minimum: 1000 events/sec (conservative; actual should be higher)"
Write-Host "  - Pipeline overhead < 1000x baseline (architecture sanity check)"
Write-Host ""
Write-Host "Total STEP 12 tests: ~9 (perf_benchmark.zig)"
Write-Host "Total Zig tests now: ~365 (was ~355 after STEP 11)"
Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"feat: step 12 - performance benchmark suite`""
Write-Host "  git push"
